    <section id="cards" className="section cards-section" onMouseEnter={() => setActive('practice')}><SectionTitle eyebrow="Active recall" title="Flashcards for the distinctions questions exploit" body="Say the answer before revealing it. If you hesitate, use the comparison table and Microsoft documentation to rebuild the distinction in your own words." /><div className="flashcard-wrap"><button className="card-arrow" aria-label="Previous flashcard" onClick={() => { setCard((card + flashcards.length - 1) % flashcards.length); setFlipped(false); }}><ChevronLeft /></button><button className={`flashcard ${flipped ? 'flipped' : ''}`} onClick={() => setFlipped(!flipped)} aria-label="Reveal flashcard answer"><div className="flash-front"><span>CONCEPT {card + 1} / {flashcards.length}</span><h3>{flashcards[card][0]}</h3><p>Click to reveal</p></div><div className="flash-back"><span>ANSWER</span><p>{flashcards[card][1]}</p></div></button><button className="card-arrow" aria-label="Next flashcard" onClick={() => { setCard((card + 1) % flashcards.length); setFlipped(false); }}><ChevronRight /></button></div></section>
